135. // Memory Region
136. //==================================================================================================
137. 
138. ///
139. /// # Description
140. ///
141. /// A memory region.
142. ///
143. #[verus_verify(external_derive)]
144. #[derive(Debug, Clone)]
145. pub struct MemoryRegion<T: Address> {
146.     name: String,
147.     start: T,
148.     size: usize,
149.     typ: MemoryRegionType,
150.     perm: AccessPermission,
151.     cache_policy: Option<MmioCachePolicy>,
152. }
153. 
154. impl<T: Address> MemoryRegion<T> {
155.     /// Maximum byte-length of a memory region name.
156.     const MEMORY_REGION_NAME_MAX: usize = 32;
157. 
158.     /// Creates a new memory region.
159.     pub fn new(
160.         name: &str,
161.         start: T,
162.         size: usize,
163.         typ: MemoryRegionType,
164.         perm: AccessPermission,
165.     ) -> Result<Self, Error> {
166.         // Check if name is too long (byte length).
167.         if name.len() > Self::MEMORY_REGION_NAME_MAX {
168.             let reason: &str = "memory region name is too long";
169.             error!("{reason} (name.len={}, NAME_MAX={})", name.len(), Self::MEMORY_REGION_NAME_MAX);
170.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
171.         }
172. 
173.         // Check if size of the memory region is valid.
174.         if size == 0 {
175.             return Err(Error::new(ErrorCode::InvalidArgument, "invalid memory region size"));
176.         }
177. 
178.         // Check if memory region is too big.
179.         let start_raw_addr: usize = start.clone().into_raw_value();
180.         let end_raw_addr: usize = match start_raw_addr.checked_add(size - 1) {
181.             Some(end_raw_addr) => end_raw_addr,
182.             None => {
183.                 return Err(Error::new(ErrorCode::TooBig, "memory region is too big"));
184.             },
185.         };
186. 
187.         // Check if memory region spans outside the address space.
188.         if end_raw_addr > T::max_addr() {
189.             return Err(Error::new(
190.                 ErrorCode::InvalidArgument,
191.                 "memory region spans outside the address space",
192.             ));
193.         }
194. 
195.         Ok(Self {
196.             name: name.to_string(),
197.             start,
198.             size,
199.             typ,
200.             perm,
201.             cache_policy: None,
202.         })
203.     }
204. 
205.     pub fn name(&self) -> String {
206.         self.name.clone()
207.     }
208. 
209.     /// Returns the first valid address that lies in the target memory region.
210.     #[verus_spec(result =>
211.         ensures
212.             // Faithful read: the returned address has the same abstract address
213.             // as the stored `start` (`spec_addr(&result) == self@.start`). `T` is
214.             // a bare `Address` (no `View` bound), so the value is projected
215.             // through the universal `spec_addr`, not `result@`.
216.             crate::hal::mem::spec_addr(&result) == self@.start,
217.     )]
218.     pub fn start(&self) -> T {
219.         // The `Address: Clone` impl is value-preserving (newtype identity), but
220.         // no clone spec is in scope yet, so `spec_addr(&clone) == spec_addr(&orig)`
221.         // is not derivable here. Discharged in the proving phase (clone spec on
222.         // the `Address` family); `admit()` is the specification-phase placeholder.
223.         proof! { admit(); }
224.         self.start.clone()
225.     }
226. 
227.     /// Returns the size of the target memory region.
228.     #[verus_spec(result =>
229.         ensures
230.             result as int == self@.size,
231.     )]
232.     pub fn size(&self) -> usize {
233.         self.size
234.     }
235. 
236.     /// Returns the type of the target memory region.
237.     pub fn typ(&self) -> MemoryRegionType {
238.         self.typ
239.     }
240. 
241.     /// Returns the permissions of the target memory region.
242.     pub fn perm(&self) -> AccessPermission {
243.         self.perm
244.     }
245. 
246.     ///
247.     /// # Description
248.     ///
249.     /// Returns the MMIO cache policy of the target memory region, if set.
250.     ///
251.     /// # Returns
252.     ///
253.     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
254.     ///
255.     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
256.         self.cache_policy
257.     }
258. 
259.     ///
260.     /// # Description
261.     ///
262.     /// Sets the MMIO cache policy of the target memory region.
263.     ///
264.     /// # Parameters
265.     ///
266.     /// - `policy`: The cache policy to assign.
267.     ///
268.     pub fn set_cache_policy(&mut self, policy: MmioCachePolicy) {
269.         self.cache_policy = Some(policy);
270.     }
271. }
272. 
273. impl<T: Address> PartialEq for MemoryRegion<T> {
274.     fn eq(&self, other: &Self) -> bool {
275.         self.name == other.name
276.             && self.start == other.start
277.             && self.size == other.size
278.             && self.typ == other.typ
279.             && self.perm == other.perm
280.             && self.cache_policy == other.cache_policy
281.     }
282. }
283. 
284. impl<T: Address> Eq for MemoryRegion<T> {}
285. 
286. impl<T: Address> PartialOrd for MemoryRegion<T> {
287.     fn partial_cmp(&self, other: &Self) -> Option<core::cmp::Ordering> {
288.         Some(self.cmp(other))
289.     }
290. }
291. 
292. impl<T: Address> Ord for MemoryRegion<T> {
293.     fn cmp(&self, other: &Self) -> core::cmp::Ordering {
294.         self.start.cmp(&other.start)
295.     }
296. }
