298. //==================================================================================================
299. // Truncated Memory Region
300. //==================================================================================================
301. 
302. ///
303. /// # Description
304. ///
305. /// A memory region that has been truncated to a multiple of a page size.
306. ///
307. #[verus_verify(external_derive)]
308. #[derive(Clone)]
309. pub struct TruncatedMemoryRegion<T: Address>(MemoryRegion<PageAligned<T>>);
310. 
311. impl<T: Address> TruncatedMemoryRegion<T> {
312.     /// Creates a new truncated memory region.
313.     pub fn new(
314.         name: &str,
315.         start: PageAligned<T>,
316.         size: usize,
317.         typ: MemoryRegionType,
318.         perm: AccessPermission,
319.     ) -> Result<Self, Error> {
320.         // Truncate the size of the memory region to a multiple of the page size.
321.         let size: usize = ::sys::mm::align_up(size, PAGE_ALIGNMENT).ok_or_else(|| {
322.             let reason: &str = "align_up overflow";
323.             error!("TruncatedMemoryRegion::new(): {reason} (name={name:?}, size={size})");
324.             Error::new(ErrorCode::InvalidArgument, reason)
325.         })?;
326.         Ok(Self(MemoryRegion::new(name, start, size, typ, perm)?))
327.     }
328. 
329.     ///
330.     /// # Description
331.     ///
332.     /// Creates a new truncated MMIO memory region with an explicit cache policy.
333.     ///
334.     /// # Parameters
335.     ///
336.     /// - `name`: Name of the memory region.
337.     /// - `start`: Page-aligned start address.
338.     /// - `size`: Size of the region in bytes (rounded up to page alignment).
339.     /// - `perm`: Access permissions for the region.
340.     /// - `cache_policy`: Caching policy that controls PWT/PCD bits in page table entries.
341.     ///
342.     /// # Returns
343.     ///
344.     /// Upon successful completion, a new [`TruncatedMemoryRegion`] with type
345.     /// [`MemoryRegionType::Mmio`] is returned. Upon failure, an error is returned instead.
346.     ///
347.     pub fn new_mmio(
348.         name: &str,
349.         start: PageAligned<T>,
350.         size: usize,
351.         perm: AccessPermission,
352.         cache_policy: MmioCachePolicy,
353.     ) -> Result<Self, Error> {
354.         let mut region: Self = Self::new(name, start, size, MemoryRegionType::Mmio, perm)?;
355.         region.0.set_cache_policy(cache_policy);
356.         Ok(region)
357.     }
358. 
359.     pub fn from_memory_region(region: MemoryRegion<T>) -> Result<Self, Error> {
360.         let cache_policy: Option<MmioCachePolicy> = region.cache_policy();
361.         let start: T = region.start().align_down(PAGE_ALIGNMENT)?;
362.         let start: PageAligned<T> = PageAligned::from_address(start)?;
363.         let name: String = region.name();
364.         let size: usize = region.size();
365.         let typ: MemoryRegionType = region.typ();
366.         let perm: AccessPermission = region.perm();
367.         let mut truncated: Self = Self::new(&name, start, size, typ, perm)?;
368.         if let Some(policy) = cache_policy {
369.             truncated.0.set_cache_policy(policy);
370.         }
371.         Ok(truncated)
372.     }
373. 
374.     pub fn name(&self) -> String {
375.         self.0.name()
376.     }
377. 
378.     /// Returns the first valid address that lies in the target memory region.
379.     #[verus_spec(result =>
380.         ensures
381.             // Faithful read, delegated to the inner region. The returned
382.             // `PageAligned<T>` carries the same abstract address as the stored
383.             // start (`spec_addr(&result) == self@.start`); page alignment of that
384.             // address follows from `self.inv()`.
385.             crate::hal::mem::spec_addr(&result) == self@.start,
386.     )]
387.     pub fn start(&self) -> PageAligned<T> {
388.         self.0.start()
389.     }
390. 
391.     /// Returns the size of the target memory region.
392.     #[verus_spec(result =>
393.         ensures
394.             result as int == self@.size,
395.     )]
396.     pub fn size(&self) -> usize {
397.         self.0.size()
398.     }
399. 
400.     /// Returns the type of the target memory region.
401.     pub fn typ(&self) -> MemoryRegionType {
402.         self.0.typ()
403.     }
404. 
405.     /// Returns the permissions of the target memory region.
406.     pub fn perm(&self) -> AccessPermission {
407.         self.0.perm()
408.     }
409. 
410.     ///
411.     /// # Description
412.     ///
413.     /// Returns the MMIO cache policy of the target memory region, if set.
414.     ///
415.     /// # Returns
416.     ///
417.     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
418.     ///
419.     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
420.         self.0.cache_policy()
421.     }
422. }
423. 
424. impl<T: Address> PartialEq for TruncatedMemoryRegion<T> {
425.     fn eq(&self, other: &Self) -> bool {
426.         self.0 == other.0
427.     }
428. }
429. 
430. impl<T: Address> Eq for TruncatedMemoryRegion<T> {}
431. 
432. impl<T: Address> PartialOrd for TruncatedMemoryRegion<T> {
433.     fn partial_cmp(&self, other: &Self) -> Option<core::cmp::Ordering> {
434.         Some(self.cmp(other))
435.     }
436. }
437. 
438. impl<T: Address> Ord for TruncatedMemoryRegion<T> {
439.     fn cmp(&self, other: &Self) -> core::cmp::Ordering {
440.         self.0.cmp(&other.0)
441.     }
442. }
443. 
444. impl<T: Address> core::fmt::Debug for TruncatedMemoryRegion<T> {
445.     fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result {
446.         write!(
447.             f,
448.             "TruncatedMemoryRegion {{ name: {}, start: {:?}, size: {}, typ: {:?}, perm: {:?}, \
449.              cache_policy: {:?} }}",
450.             self.name(),
451.             self.start(),
452.             self.size(),
453.             self.typ(),
454.             self.perm(),
455.             self.cache_policy()
456.         )
457.     }
458. }
459. 
