461. // Standalone Functions
462. //==================================================================================================
463. 
464. impl TruncatedMemoryRegion<PhysicalAddress> {
465.     /// Attempts to create a virtual memory region from a physical memory region.
466.     pub fn from_virtual_memory_region(region: MemoryRegion<VirtualAddress>) -> Result<Self, Error> {
467.         let name: String = region.name();
468.         let start: PageAligned<PhysicalAddress> =
469.             PageAligned::from_address(PhysicalAddress::from_virtual_address(region.start())?)?;
470.         let size: usize = region.size();
471.         let typ: MemoryRegionType = region.typ();
472.         let perm: AccessPermission = region.perm();
473.         TruncatedMemoryRegion::new(&name, start, size, typ, perm)
474.     }
475. }
