     /// Returns the MMIO cache policy of the target memory region, if set.
     ///
     /// # Returns
     ///
     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
     ///
     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
